using UnityEngine;

namespace Astrea;

public class DiceVisuals : MonoBehaviour
{
	[Header("Spinning Dice")]
	[SerializeField]
	private float spinDuration;

	[SerializeField]
	private Vector3 diceStartSpinRotation;

	[SerializeField]
	private bool rightDirection;

	[Header("Components")]
	[SerializeField]
	private DiceFaceInstance3D[] diceFaceInstances;

	[SerializeField]
	private Transform diceModelHolder;

	private Dice dice;

	private Coroutine spinCoroutine;

	private DiceTrail diceTrail;

	private GameObject diceTrailObj;

	[SerializeField]
	private GameObject diceModel;

	public void Initialize(Dice dice, bool hideDiceFace)
	{
		this.dice = dice;
		diceModel = ReferenceSingleton<PoolHandler>.Instance.GetObject(dice.DiceTier.Dice3DPrefab.name, diceModelHolder);
		diceModel.transform.localRotation = Quaternion.identity;
		SetDiceTossingLayer();
		base.transform.localScale = Vector3.one * 0.45f;
		UpdateDiceFaces(hideDiceFace);
	}

	public void SetupDiceToRoll()
	{
		SetDiceTossingLayer();
		StartSpinning();
		SetDiceVisuals();
	}

	public void InitializeAsDicePreview(Dice dice, bool mainCamera, CompendiumItemState compendiumItemState = CompendiumItemState.Discovered)
	{
		diceModel = ReferenceSingleton<PoolHandler>.Instance.GetObject(dice.DiceTier.Dice3DPrefab.name, diceModelHolder);
		diceModel.transform.localRotation = Quaternion.identity;
		if (mainCamera)
		{
			SetDefaultLayer();
		}
		else
		{
			SetDicePreviewLayer();
		}
		base.transform.localScale = Vector3.one * 0.5f;
		this.dice = dice;
		SetDiceVisuals();
		StartSpinning();
		UpdateDiceFaces(hideDiceFace: false, compendiumItemState);
	}

	public void StartSpinning()
	{
		base.transform.eulerAngles = diceStartSpinRotation;
		Spin();
	}

	private void Spin()
	{
		if (spinCoroutine != null)
		{
			StopCoroutine(spinCoroutine);
		}
		Vector3 startRotation = base.transform.rotation.eulerAngles;
		int num = (rightDirection ? 1 : (-1));
		Vector3 endRotation = startRotation + new Vector3(0f, 360f, 0f) * num;
		spinCoroutine = StartCoroutine(CoroutineUtility.CurveRoutine(spinDuration, delegate(float t, float v)
		{
			base.transform.eulerAngles = Vector3.Lerp(startRotation, endRotation, v);
		}, delegate
		{
			Spin();
		}));
	}

	public void OnRollDice()
	{
		StopGlowParticle();
		if (spinCoroutine != null)
		{
			StopCoroutine(spinCoroutine);
		}
	}

	public void StoreDicePreview()
	{
		diceTrail.StoreParticlesPreviews();
		StoreDiceModel();
	}

	public void StoreDiceModel()
	{
		Debug.Log("!!!!!!!!!!!!!!!!!!!StoreDiceModel called: " + dice.name);
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(diceModel);
		diceModel = null;
	}

	public void StoreDiceTrailParticles()
	{
		if (diceTrail != null)
		{
			diceTrail.StoreParticles();
		}
	}

	public void StopGlowParticle()
	{
		diceTrail.StopGlow();
	}

	public void StoreParticlesPreviews()
	{
		diceTrail.StoreParticlesPreviews();
	}

	private void SetDiceVisuals(bool spawnTrailVFX = true)
	{
		if (spawnTrailVFX)
		{
			diceTrailObj = ReferenceSingleton<PoolHandler>.Instance.GetObject(dice.DiceTier.DiceTrailPrefab.name, base.transform.position);
			diceTrail = diceTrailObj.GetComponent<DiceTrail>();
			diceTrail.Initialize(base.transform);
		}
	}

	public void DestroyTrail()
	{
		if ((bool)diceTrailObj)
		{
			Object.Destroy(diceTrailObj);
			diceTrailObj = null;
		}
	}

	public void UpdateDiceFaces(bool hideDiceFace, CompendiumItemState compendiumItemState = CompendiumItemState.Discovered)
	{
		if (dice.GetDiceFaces().Length == 0)
		{
			return;
		}
		for (int i = 0; i < diceFaceInstances.Length; i++)
		{
			diceFaceInstances[i].ToggleHideDiceFace(hideDiceFace);
			if (!hideDiceFace)
			{
				diceFaceInstances[i].SetDiceFace(dice.GetDiceFaces()[i], dice.DiceTier, hideDiceFace, hideDiceFace: false, compendiumItemState);
			}
		}
	}

	public void SetNoOutlineLayer()
	{
		base.gameObject.transform.SetLayerAndChildLayers(6);
	}

	public void SetDiceTossingLayer()
	{
		GetComponentInChildren<DiceInstanceOutlineHandler>().SetTransitionOutlineLayerNoColor();
	}

	public void SetDicePreviewLayer()
	{
		base.gameObject.transform.SetLayerAndChildLayers(10);
	}

	public void SetDefaultLayer()
	{
		base.gameObject.transform.SetLayerAndChildLayers(0);
	}

	public void ToggleCompanionDice(bool value)
	{
		for (int i = 0; i < diceFaceInstances.Length; i++)
		{
			diceFaceInstances[i].ToggleCompanionDice(value);
		}
	}

	public void UpdateDice(Dice dice)
	{
		this.dice = dice;
	}
}
